import{_ as t,o as a,c as s,a5 as n}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"TikTools 4.2.2","description":"","frontmatter":{"title":"TikTools 4.2.2","docId":"releases.4.2.2","translationKey":"releases.4.2.2","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2a82a33b45407681d8d052a8a16e40dbc83f6889b3e4874cf05f95cc4aa44896","translationRevision":"395642b4f8283af66698dc8019794b67fc9c26976e3106fa8dbab9ced495de8b","order":40},"headers":[],"relativePath":"fr/releases/4.2.2.md","filePath":"fr/releases/4.2.2.md","lastUpdated":1794611623000}'),i={name:"fr/releases/4.2.2.md"};function r(o,e,l,u,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="tiktools-422" tabindex="-1">TikTools 4.2.2 <a class="header-anchor" href="#tiktools-422" aria-label="Permalink to &quot;TikTools 4.2.2 {#tiktools-422}&quot;">​</a></h1><h2 id="goal-publication-status-and-prerequisites" tabindex="-1">Objectif, état de publication et prérequis <a class="header-anchor" href="#goal-publication-status-and-prerequisites" aria-label="Permalink to &quot;Objectif, état de publication et prérequis {#goal-publication-status-and-prerequisites}&quot;">​</a></h2><p>Utilisez ces notes pour examiner les changements Variables implémentés et les conditions de publication restantes. Statut au 13 novembre 2026 : <strong>la compilation de l’application et les vérifications CI réussissent ; les installateurs Linux sont désormais empaquetés et l’empaquetage Windows a réussi, mais le contrôle de démarrage AppImage a échoué à cause d’une dépendance XKB d’exécution manquante et 4.2.2 n’est pas publiée</strong>. Aucune publication réussie d’installateur, vérification des sommes de contrôle téléversées ou promotion des flux de mise à jour n’est revendiquée.</p><p>La compilation s’exécute dans <code>hernan-lc/TikTools-app</code> avec <code>RELEASE_REPO=nglmercer/TikTools-app</code> comme cible de publication prévue. Les ressources candidates 4.2.1 existantes restent distinctes. Pour une version de test disponible, utilisez la <a href="./4.2.1-rc.3.html">préversion RC3 publiée</a> ; vérifiez la <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">liste des versions</a> pour les ressources réellement téléchargeables.</p><p>Ces fonctionnalités Cloud et de collaboration restent expérimentales. Les tests du code source/d’une version candidate nécessitent un hôte compatible compilé séparément, un profil isolé, des Variables non secrètes enregistrées, une session/un consentement Cloud actuels et le pont natif annoncé. Consultez la <a href="./../developer/setup.html">configuration de développement</a>.</p><h2 id="implemented-variables-changes" tabindex="-1">Changements Variables implémentés <a class="header-anchor" href="#implemented-variables-changes" aria-label="Permalink to &quot;Changements Variables implémentés {#implemented-variables-changes}&quot;">​</a></h2><p>Variables utilise le panneau Changes partagé. L’envoi traite uniquement les valeurs natives enregistrées sélectionnées ; le téléchargement actualise uniquement le cache. Appliquer une valeur Cloud examinée et retirer sa copie Cloud sont des actions distinctes. Le retrait conserve la valeur locale et sa classification secrète. Les brouillons locaux non enregistrés doivent d’abord être enregistrés ou abandonnés, et les anciens hôtes sans pont masquent la commande.</p><p>L’hôte vérifie la session exacte, le consentement, la révision locale et la comparaison ciblée. Les modifications en file peuvent être remplacées ou annulées. La récupération protégée par époque gère les téléversements incertains et le retrait après qu’une valeur devient secrète sans rejouer sa valeur précédente. Les générations de décision avancent après accusé de réception. Les Variables non cochées et les files des autres sections restent hors de l’envoi sélectionné.</p><p>Les grands entiers conservent leur texte natif exact lors de l’édition dans le navigateur et de la comparaison/adoption. Enregistrer une autre variable préserve le texte entier intact. Les types restent texte, nombre, booléen, liste et secret local. Les valeurs secrètes ou bloquées n’ont ni différence de valeur ni commande d’envoi ou d’adoption. Cet adaptateur n’a pas de commande de fusion de champs, forçage, historique ou synchronisation automatique.</p><h2 id="review-steps-and-expected-result" tabindex="-1">Étapes d’examen et résultat attendu <a class="header-anchor" href="#review-steps-and-expected-result" aria-label="Permalink to &quot;Étapes d’examen et résultat attendu {#review-steps-and-expected-result}&quot;">​</a></h2><ol><li>Dans une version candidate compatible isolée, enregistrez une valeur texte anodine telle que <code>demoGreeting = &quot;Bonjour&quot;</code>. L’enregistrement seul doit rester local.</li><li>Ouvrez Variables → Changes lorsque l’hôte annonce sa prise en charge. Examinez la comparaison locale/Cloud enregistrée et choisissez uniquement la ligne voulue pour Send.</li><li>Traitez le téléchargement comme une mise à jour du cache. Examinez puis utilisez Apply séparément avant d’attendre une modification locale.</li><li>Utilisez le retrait explicite pour supprimer une copie Cloud. La valeur locale et sa classification secrète doivent rester intactes.</li><li>Si la session, le consentement, la révision ou une cible changent, actualisez la comparaison et examinez à nouveau. Résolvez un résultat incertain via son parcours de récupération existant plutôt que de répéter un téléversement comme nouvelle opération.</li></ol><p>Ce sont les comportements attendus du code source, pas des résultats de validation en production nouvellement exécutée.</p><h2 id="ci-corrections-recovery-and-unfinished-work" tabindex="-1">Corrections CI, récupération et travail inachevé <a class="header-anchor" href="#ci-corrections-recovery-and-unfinished-work" aria-label="Permalink to &quot;Corrections CI, récupération et travail inachevé {#ci-corrections-recovery-and-unfinished-work}&quot;">​</a></h2><p>Le code corrige l’ordre des modules de test, l’activation SemVer des préversions d’une fixture de cycle de vie et la lecture bornée d’en-tête complet d’un serveur de test. La politique de compatibilité des plugins en production reste inchangée. Le processus de publication exige un démarrage AppImage Linux avec profil isolé, des vérifications de contenu des installateurs, un téléversement immuable, des sommes de contrôle téléchargées et une publication de flux signés. L’<a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43469055839" target="_blank" rel="noreferrer">exécution de récupération</a> a généré des installateurs Linux après avoir empêché le nettoyage linuxdeploy imbriqué de supprimer le répertoire d’extraction de son parent. La vérification suivante exigeait à tort une classification d’installation FUSE tout en utilisant extraction et exécution. Les outils de récupération distinguent désormais le démarrage extrait de l’installation montée ; le système natif de mise à jour rejette toujours les dispositions extraites. L’<a href="https://github.com/hernan-lc/TikTools-app/actions/runs/43484544700" target="_blank" rel="noreferrer">unique relance autorisée</a> a réussi l’empaquetage et les deux sondes CLI, puis a échoué avant frontend-ready car libxkbcommon-x11 ne pouvait pas être chargée. Les travaux restants ont été annulés pour éviter de dépenser des minutes sur une publication devenue impossible. Le correctif installe les paquets XKB et embarque la bibliothèque chargée dynamiquement avec ses dépendances ; les vérifications locales de chargement Ubuntu réussissent. Un démarrage AppImage corrigé complet et la publication restent non vérifiés ; aucune exécution Actions supplémentaire n’a été lancée.</p><p>Tant que la récupération de l’empaquetage et la publication vérifiée ne sont pas terminées, utilisez les ressources publiées et suivez le <a href="./../user/updates.html">guide des mises à jour</a>. Gardez des sauvegardes de profils ; remplacer un binaire n’annule pas les migrations de base de données. Pour les erreurs Variables, préservez l’état en attente, la version et les détails de requête/erreur expurgés avec <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>.</p><p>La découverte par pseudonyme Teams et les invitations liées au destinataire dépendent toujours du serveur <code>6a69c99</code> et de la migration <code>20261113000001_remote_invitation_recipients.sql</code>. Cette compilation applicative ne déploie pas le serveur. Le transport Cloud Automations, les révisions Overlay, la provenance historique/des branches et la présentation restante de collaboration sont des travaux séparés. Le détenteur historique du verrou SQLite LIVE reste non identifié. Les vérifications locales/avec faux compte n’établissent pas la synchronisation en production avec un compte connecté ni la compatibilité Teams.</p><p>Le <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.2.md" target="_blank" rel="noreferrer">rapport de version original</a> est conservé comme preuve datée. Revenez à l’<a href="./">index des versions</a>.</p>',17)])])}const v=t(i,[["render",r]]);export{m as __pageData,v as default};
